use super::*;
use atlas_faiss_probe::overlay::{DeltaSnapshot,FlatOverlay};
use std::collections::{BTreeMap,HashMap,HashSet};
use std::io::Write;

type Records=BTreeMap<String,Vec<Value>>;
fn group(rows:&[Value])->Result<Records,String>{let mut result=Records::new();for row in rows {let id=row["id"].as_str().ok_or("invalid source id")?;result.entry(id.to_owned()).or_default().push(row.clone());}Ok(result)}
fn valid_generation(name:&str)->bool{name.starts_with("gen-")&&name.chars().all(|c|c.is_ascii_alphanumeric()||c=='-')}
fn current(dir:&Path)->Result<String,String>{let generation=std::fs::read_to_string(dir.join("current")).map_err(|e|e.to_string())?;if !valid_generation(&generation){return Err("invalid generation".into())}Ok(generation)}
fn content_hash(data:&[u8])->String{format!("{:x}",Sha256::digest(data))}
// Keep a legacy-readable base in every overlay generation. Hard links avoid
// rewriting unchanged vectors; filesystems without links use verified copies.
fn embed_base(base:&Path,stage:&Path)->Result<(),String>{
 use std::os::unix::fs::OpenOptionsExt;
 for name in ["metadata.json","index.faiss"] {let source=base.join(name);let dest=stage.join(name);let metadata=std::fs::symlink_metadata(&source).map_err(|e|e.to_string())?;if !metadata.is_file()||metadata.file_type().is_symlink(){return Err("invalid base file".into())}if std::fs::hard_link(&source,&dest).is_err(){let mut input=std::fs::OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&source).map_err(|e|e.to_string())?;let mut out=std::fs::OpenOptions::new().write(true).create_new(true).open(&dest).map_err(|e|e.to_string())?;std::io::copy(&mut input,&mut out).map_err(|e|e.to_string())?;out.sync_all().map_err(|e|e.to_string())?;}if digest(&source)?!=digest(&dest)?{return Err("base copy verification failed".into())}}
 Ok(())
}
fn read_json(path:&Path)->Result<Value,String>{serde_json::from_slice(&std::fs::read(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())}
fn records(value:&Value)->Result<&Vec<Value>,String>{value["records"].as_array().ok_or_else(||"invalid records".into())}
struct Loaded {active_generation:String,base_generation:String,base_data:Value,base_index:Index,snapshot:Option<DeltaSnapshot>,delta_rows:Vec<Value>}
fn load(dir:&Path,key:&str)->Result<Loaded,String>{
 let generation=current(dir)?;let active_generation=generation.clone();let active=dir.join(&generation);let manifest_path=active.join("overlay.json");
 let manifest=if manifest_path.exists(){let bytes=std::fs::read(&manifest_path).map_err(|e|e.to_string())?;let expected=std::fs::read_to_string(active.join("overlay.sha256")).map_err(|e|e.to_string())?;if content_hash(&bytes)!=expected{return Err("overlay manifest checksum mismatch".into())}Some(serde_json::from_slice::<Value>(&bytes).map_err(|e|e.to_string())?)}else{None};
 let base_generation=match &manifest{Some(m)=>m["base_generation"].as_str().ok_or("missing base generation")?.to_owned(),None=>generation};
 if !valid_generation(&base_generation){return Err("invalid base generation".into())}let base_generation=if dir.join(&base_generation).is_dir(){base_generation}else if active.join("metadata.json").is_file()&&active.join("index.faiss").is_file(){active_generation.clone()}else{return Err("base generation missing".into())};let base=dir.join(&base_generation);let meta_path=base.join("metadata.json");let base_data=read_json(&meta_path)?;
 if base_data["index_sha256"]!=digest(&base.join("index.faiss"))?{return Err("base checksum mismatch".into())}let base_index=Index::load(&base.join("index.faiss")).map_err(str::to_string)?;if base_index.count()!=records(&base_data)?.len() as i64{return Err("base count mismatch".into())}
 let (snapshot,delta_rows)=if let Some(m)=manifest {if m["key"]!=base_data["key"]||m["base_metadata_sha256"]!=digest(&meta_path)?||m["base_index_sha256"]!=base_data["index_sha256"]{return Err("overlay base incompatible".into())}let bytes=std::fs::read(active.join("delta.faiss")).map_err(|e|e.to_string())?;if m["delta_sha256"]!=content_hash(&bytes){return Err("delta checksum mismatch".into())}let changed_keys=serde_json::from_value(m["changed_keys"].clone()).map_err(|e|format!("{e}"))?;let records=serde_json::from_value(m["delta_records"].clone()).map_err(|e|format!("{e}"))?;let removed=serde_json::from_value(m["removed"].clone()).map_err(|e|format!("{e}"))?;let hidden=serde_json::from_value(m["hidden"].clone()).map_err(|e|format!("{e}"))?;let rows=m["delta_metadata"].as_array().ok_or("invalid delta metadata")?.clone();let snapshot=DeltaSnapshot{index:bytes,changed_keys,records,removed,hidden};if snapshot.records.len()!=rows.len(){return Err("delta metadata count mismatch".into())}for((id,_),row)in snapshot.records.iter().zip(&rows){if row["id"].as_str()!=Some(id){return Err("delta metadata id mismatch".into())}}(Some(snapshot),rows)}else{(None,vec![])};
 if base_data["key"]!=key{return Err("model mismatch".into())}
 Ok(Loaded{active_generation,base_generation,base_data,base_index,snapshot,delta_rows})
}
fn visible(base:&[Value],snapshot:Option<&DeltaSnapshot>,delta_rows:&[Value])->Result<Records,String>{let mut result=group(base)?;if let Some(s)=snapshot{for key in s.changed_keys.iter().chain(s.removed.iter()).chain(s.hidden.iter()){result.remove(key);}for (id,rows) in group(delta_rows)?{if !s.changed_keys.contains(&id){return Err("unexpected delta row".into())}if !s.hidden.contains(&id){result.insert(id,rows);}}}Ok(result)}
fn metadata(doc:&Source<'_>)->Result<Vec<Value>,String>{let mut rows=Vec::new();for(field,text)in[("body",doc.body),("description",doc.description)]{if text.trim().is_empty(){continue}for c in split(text)?{let fragment=c["text"].as_str().ok_or("missing text")?;rows.push(json!({"id":doc.id,"title":doc.title,"field":field,"input_hash":input_hash(&format!("{}\n{fragment}",doc.title)),"text":fragment,"start":c["start"],"end":c["end"],"start_utf16":c["start_utf16"],"end_utf16":c["end_utf16"]}));}}if doc.body.trim().is_empty()&&!doc.title.trim().is_empty(){rows.push(json!({"id":doc.id,"title":doc.title,"field":"title","input_hash":input_hash(doc.title),"text":doc.title,"start":null,"end":null}));}Ok(rows)}
// Reindex retained trash when the model changes, then hide it before publication.
fn rebuild_with_trash(model:&Encoder,docs:&[Source<'_>],images:impl Iterator<Item=Result<(String,String,Vec<u8>,String),String>>,trash:&[String],dir:&Path,should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<String,String>{
 let base_generation=prepare_sources_with_progress(model,docs,images,dir,&should_continue,&progress)?;let initial_base=dir.join(&base_generation);
 if trash.is_empty(){return Ok(base_generation)}
 let result=(||->Result<Option<String>,String>{
  if !should_continue(){return Err("indexing cancelled".into())}let meta=read_json(&initial_base.join("metadata.json"))?;let rows=records(&meta)?;let index=Index::load(&initial_base.join("index.faiss")).map_err(str::to_string)?;let keys=rows.iter().map(|r|r["id"].as_str().map(str::to_owned).ok_or("invalid source id")).collect::<Result<Vec<_>,_>>()?;let mut overlay=FlatOverlay::new(index,keys)?;for id in trash{if overlay.has_key(id){overlay.hide(id)?;}}if !overlay.has_hidden(){return Ok(None)}
  let snap=overlay.snapshot_delta()?;let generation=format!("gen-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos());let stage=dir.join(&generation);let base_name=format!("{generation}-base");let base=dir.join(&base_name);std::fs::create_dir(&stage).map_err(|e|e.to_string())?;let mut owns_base=false;
  let prepared=(||->Result<(),String>{std::fs::create_dir(&base).map_err(|e|e.to_string())?;owns_base=true;for name in ["metadata.json","index.faiss"]{std::fs::rename(initial_base.join(name),base.join(name)).map_err(|e|e.to_string())?;}std::fs::remove_dir(&initial_base).map_err(|e|e.to_string())?;std::fs::File::open(&base).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;if !should_continue(){return Err("indexing cancelled".into())}
   embed_base(&base,&stage)?;let delta=stage.join("delta.faiss");std::fs::write(&delta,&snap.index).map_err(|e|e.to_string())?;std::fs::File::open(&delta).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;let value=json!({"key":model.identity(),"base_generation":base_name,"base_metadata_sha256":digest(&base.join("metadata.json"))?,"base_index_sha256":digest(&base.join("index.faiss"))?,"delta_sha256":content_hash(&snap.index),"changed_keys":snap.changed_keys,"delta_records":snap.records,"removed":snap.removed,"hidden":snap.hidden,"delta_metadata":[],"encoded_count":meta["encoded_count"]});let bytes=serde_json::to_vec(&value).map_err(|e|e.to_string())?;let path=stage.join("overlay.json");std::fs::write(&path,&bytes).map_err(|e|e.to_string())?;std::fs::File::open(path).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;let checksum=stage.join("overlay.sha256");std::fs::write(&checksum,content_hash(&bytes)).map_err(|e|e.to_string())?;std::fs::File::open(checksum).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;std::fs::File::open(&stage).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;Ok(())})();if prepared.is_err(){let _=std::fs::remove_dir_all(&stage);if owns_base{let _=std::fs::remove_dir_all(&base);}}prepared?;Ok(Some(generation))
 })();match result{Ok(Some(g))=>Ok(g),Ok(None)=>Ok(base_generation),Err(e)=>{let _=std::fs::remove_dir_all(&initial_base);Err(e)}}
}
/// Build a new delta generation. The existing base stays immutable and referenced by name.
pub struct Prepared {pub generation:String,pub owned:bool}
pub fn prepare(model:&Encoder,docs:&[Source<'_>],images:impl Iterator<Item=Result<(String,String,Vec<u8>,String),String>>,dir:&Path,should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<String,String>{prepare_with_trash(model,docs,images,&[],dir,should_continue,progress).map(|v|v.generation)}
/// When independent index histories coexist, rebuild from the current sources,
/// including the trash, before publishing. Neither cache establishes which is newer.
pub fn prepare_fresh_with_trash(model:&Encoder,docs:&[Source<'_>],images:impl Iterator<Item=Result<(String,String,Vec<u8>,String),String>>,trash:&[String],dir:&Path,should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<Prepared,String>{
 rebuild_with_trash(model,docs,images,trash,dir,should_continue,progress).map(|generation|Prepared{generation,owned:true})
}
pub fn prepare_with_trash(model:&Encoder,docs:&[Source<'_>],images:impl Iterator<Item=Result<(String,String,Vec<u8>,String),String>>,trash:&[String],dir:&Path,should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<Prepared,String>{
 if !dir.join("current").is_file(){return rebuild_with_trash(model,docs,images,trash,dir,should_continue,progress).map(|generation|Prepared{generation,owned:true})}
 let loaded=match load(dir,model.identity()){Ok(x)=>x,Err(e) if e=="model mismatch"=>return rebuild_with_trash(model,docs,images,trash,dir,should_continue,progress).map(|generation|Prepared{generation,owned:true}),Err(e)=>return Err(e)};
 let base_rows=records(&loaded.base_data)?;let old=visible(base_rows,loaded.snapshot.as_ref(),&loaded.delta_rows)?;
 let trash_set:HashSet<&str>=trash.iter().map(String::as_str).collect();let mut desired=Records::new();for doc in docs{if !should_continue(){return Err("indexing cancelled".into())}if !trash_set.contains(doc.id){desired.insert(doc.id.to_owned(),metadata(doc)?);}}
 let delta_index=loaded.snapshot.as_ref().map(|s|Index::from_memory(&s.index).map_err(str::to_string)).transpose()?;
 let mut vector_cache=HashMap::<String,(bool,i64)>::new();for(i,row)in base_rows.iter().enumerate(){if let Some(key)=row["input_hash"].as_str(){vector_cache.insert(key.to_owned(),(false,i as i64));}}
 for(i,row)in loaded.delta_rows.iter().enumerate(){if let Some(key)=row["input_hash"].as_str(){vector_cache.insert(key.to_owned(),(true,i as i64));}}
 let mut new_images=HashMap::<String,[f32;512]>::new();let mut encoded_count=0usize;
 for image in images{let(id,title,bytes,mime)=match image{Ok(i)=>i,Err(e)=>{eprintln!("Atlas: image indexing skipped: {e}");continue}};if !should_continue(){return Err("indexing cancelled".into())}if trash_set.contains(id.as_str()){continue}let key=format!("image:{:x}",Sha256::digest(&bytes));if !vector_cache.contains_key(&key)&&!new_images.contains_key(&key){let vector:[f32;512]=match model.encode_image(&bytes,&mime).and_then(|v|v.try_into().map_err(|_|"invalid dimensions".into())){Ok(v)=>v,Err(e)=>{eprintln!("Atlas: image indexing skipped: {e}");continue}};new_images.insert(key.clone(),vector);encoded_count+=1;}desired.entry(id.clone()).or_default().push(json!({"id":id,"title":title,"field":"image","input_hash":key,"text":"","start":null,"end":null}));}
 desired.retain(|_,v|!v.is_empty());let mut mutations=Vec::new();let mut new_meta=BTreeMap::new();let mut new_texts=HashMap::<String,[f32;512]>::new();
 for(id,rows)in &desired{if old.get(id)==Some(rows){continue}let mut vectors=Vec::with_capacity(rows.len());for(i,row)in rows.iter().enumerate(){if !should_continue(){return Err("indexing cancelled".into())}let key=row["input_hash"].as_str().ok_or("missing input hash")?;let vector=if let Some((delta,at))=vector_cache.get(key){if *delta{delta_index.as_ref().ok_or("missing delta")?.reconstruct(*at).map_err(str::to_string)?}else{loaded.base_index.reconstruct(*at).map_err(str::to_string)?}}else if let Some(v)=new_images.get(key){*v}else if let Some(v)=new_texts.get(key){*v}else{let title=row["title"].as_str().ok_or("missing title")?;let text=row["text"].as_str().ok_or("missing text")?;let input=if row["field"]=="title"{title.to_owned()}else{format!("{title}\n{text}")};let v:[f32;512]=model.encode(&input,false)?.try_into().map_err(|_|"invalid dimensions")?;new_texts.insert(key.to_owned(),v);encoded_count+=1;v};vectors.push(vector);progress(row["title"].as_str().unwrap_or(""),i+1,rows.len());}new_meta.insert(id.clone(),rows.clone());mutations.push((id.clone(),Some(vectors)));}
 for id in old.keys(){if !desired.contains_key(id)&&!trash_set.contains(id.as_str()){mutations.push((id.clone(),None));}}
 let purged_visible=mutations.iter().any(|(_,value)|value.is_none());
 let old_hidden:HashSet<String>=loaded.snapshot.as_ref().map(|s|s.hidden.iter().cloned().collect()).unwrap_or_default();
 let purged_hidden=old_hidden.iter().any(|id|!trash_set.contains(id.as_str())&&!desired.contains_key(id));
 for id in &old_hidden{if !trash_set.contains(id.as_str())&&!desired.contains_key(id){mutations.push((id.clone(),None));}}
 let hide_change=old.keys().any(|id|!desired.contains_key(id)&&trash_set.contains(id.as_str()))||old_hidden.iter().any(|id|desired.contains_key(id)||!trash_set.contains(id.as_str()));
 if mutations.is_empty()&&!hide_change{return Ok(Prepared{generation:loaded.active_generation,owned:false})}
 let keys=base_rows.iter().map(|r|r["id"].as_str().unwrap_or("").to_owned()).collect::<Vec<_>>();
 let mut overlay=if let Some(s)=loaded.snapshot{FlatOverlay::from_snapshot(loaded.base_index,keys,s)?}else{FlatOverlay::new(loaded.base_index,keys)?};
 let changed:HashSet<String>=mutations.iter().map(|(id,_)|id.clone()).chain(old_hidden.iter().filter(|id|!trash_set.contains(id.as_str())&&!desired.contains_key(*id)).cloned()).collect();let mut delta_groups=group(&loaded.delta_rows)?;for id in &changed {delta_groups.remove(id);}for(id,rows)in new_meta{delta_groups.insert(id,rows);}
 overlay.apply_batch(mutations)?;
 for id in &old_hidden{if desired.contains_key(id){overlay.revive(id)?;}}
 for id in trash{if overlay.has_key(id){overlay.hide(id)?;}}
 let snapshot=overlay.snapshot_delta()?;let mut delta_metadata=Vec::with_capacity(snapshot.records.len());for(id,pos)in &snapshot.records{let row=delta_groups.get(id).and_then(|v|v.get(*pos)).ok_or("delta metadata missing")?;delta_metadata.push(row.clone());}
 if !should_continue(){return Err("indexing cancelled".into())}
 let generation=format!("gen-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos());let stage=dir.join(&generation);std::fs::create_dir(&stage).map_err(|e|e.to_string())?;
 let compacted_base=dir.join(format!("{generation}-base"));let mut owns_compacted_base=false;
 let result=(||->Result<(),String>{
  // Compaction also removes physically purged vectors. Hidden vectors must survive undo.
  let compact=purged_visible||purged_hidden||snapshot.records.len()>1024;
  let mut base_generation=loaded.base_generation.clone();let mut base_metadata_sha=digest(&dir.join(&base_generation).join("metadata.json"))?;let mut base_index_sha=loaded.base_data["index_sha256"].as_str().ok_or("missing base digest")?.to_owned();let mut persisted_snapshot=snapshot;
  let mut persisted_rows=delta_metadata;
  if compact {
   let(index,layout)=overlay.materialize_cancellable(true,&should_continue)?;let base_groups=group(base_rows)?;let changed_keys:HashSet<_>=persisted_snapshot.changed_keys.iter().collect();let mut combined=Vec::with_capacity(layout.len());for(id,pos)in &layout{let rows=if changed_keys.contains(id){delta_groups.get(id)}else{base_groups.get(id)};combined.push(rows.and_then(|v|v.get(*pos)).ok_or("missing compacted metadata")?.clone());}
   if !should_continue(){return Err("indexing cancelled".into())}
   let target=if overlay.has_hidden(){std::fs::create_dir(&compacted_base).map_err(|e|e.to_string())?;owns_compacted_base=true;&compacted_base}else{&stage};let path=target.join("index.faiss");index.save(&path).map_err(str::to_string)?;std::fs::File::open(&path).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;let metadata=json!({"key":model.identity(),"binary_diagnostic":model.diagnostic(),"index_sha256":digest(&path)?,"encoded_count":encoded_count,"records":combined});let path=target.join("metadata.json");let mut f=std::io::BufWriter::new(std::fs::File::create(&path).map_err(|e|e.to_string())?);serde_json::to_writer(&mut f,&metadata).map_err(|e|e.to_string())?;f.flush().map_err(|e|e.to_string())?;drop(f);std::fs::File::open(&path).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;std::fs::File::open(target).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;
   if !overlay.has_hidden(){return Ok(())}
   let keys=layout.into_iter().map(|(id,_)|id).collect();let mut fresh=FlatOverlay::new(index,keys)?;for id in overlay.hidden_keys(){fresh.hide(&id)?;}persisted_snapshot=fresh.snapshot_delta()?;persisted_rows=vec![];base_generation=format!("{generation}-base");base_metadata_sha=digest(&compacted_base.join("metadata.json"))?;base_index_sha=digest(&compacted_base.join("index.faiss"))?;
  }
  embed_base(&dir.join(&base_generation),&stage)?;let path=stage.join("delta.faiss");std::fs::write(&path,&persisted_snapshot.index).map_err(|e|e.to_string())?;std::fs::File::open(&path).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;let manifest=json!({"key":model.identity(),"base_generation":base_generation,"base_metadata_sha256":base_metadata_sha,"base_index_sha256":base_index_sha,"delta_sha256":content_hash(&persisted_snapshot.index),"changed_keys":persisted_snapshot.changed_keys,"delta_records":persisted_snapshot.records,"removed":persisted_snapshot.removed,"hidden":persisted_snapshot.hidden,"delta_metadata":persisted_rows,"encoded_count":encoded_count});let path=stage.join("overlay.json");let mut file=std::fs::File::create(&path).map_err(|e|e.to_string())?;let bytes=serde_json::to_vec(&manifest).map_err(|e|e.to_string())?;file.write_all(&bytes).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;let checksum=stage.join("overlay.sha256");std::fs::write(&checksum,content_hash(&bytes)).map_err(|e|e.to_string())?;std::fs::File::open(checksum).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;std::fs::File::open(&stage).and_then(|f|f.sync_all()).map_err(|e|e.to_string())?;Ok(())})();if result.is_err(){let _=std::fs::remove_dir_all(&stage);if owns_compacted_base{let _=std::fs::remove_dir_all(&compacted_base);}}result?;Ok(Prepared{generation,owned:true})
}
/// Recheck all references under the workspace lock before publishing a staged generation.
pub fn validate_prepared(dir:&Path,generation:&str,identity:&str)->Result<(),String>{
 if !valid_generation(generation){return Err("invalid generation".into())}let stage=dir.join(generation);if !stage.is_dir(){return Err("base generation missing".into())}let base=match base_generation(dir,generation)?{Some(name)=>{let path=dir.join(&name);if !path.is_dir(){return Err("base generation missing".into())}let manifest=read_json(&stage.join("overlay.json"))?;let metadata_path=path.join("metadata.json");if manifest["key"]!=identity||manifest["base_metadata_sha256"]!=digest(&metadata_path)?||manifest["base_index_sha256"]!=digest(&path.join("index.faiss"))?||manifest["delta_sha256"]!=digest(&stage.join("delta.faiss"))?{return Err("prepared index checksum mismatch".into())}path},None=>stage};let metadata=read_json(&base.join("metadata.json"))?;if metadata["key"]!=identity||metadata["index_sha256"]!=digest(&base.join("index.faiss"))?{return Err("prepared base checksum mismatch".into())}Ok(())
}
/// Remove only an unpublished generation and the compacted base that it created.
pub fn discard_prepared(dir:&Path,generation:&str)->Result<(),String>{
 if !valid_generation(generation){return Err("invalid generation".into())}if std::fs::read_to_string(dir.join("current")).ok().as_deref()==Some(generation){return Ok(())}
 let own_base=format!("{generation}-base");let base=base_generation(dir,generation)?;std::fs::remove_dir_all(dir.join(generation)).map_err(|e|e.to_string())?;if base.as_deref()==Some(own_base.as_str()){std::fs::remove_dir_all(dir.join(own_base)).map_err(|e|e.to_string())?;}Ok(())
}
/// Return the immutable base generation referenced by a published delta generation.
pub fn base_generation(dir:&Path,generation:&str)->Result<Option<String>,String>{if !valid_generation(generation){return Err("invalid generation".into())}let path=dir.join(generation).join("overlay.json");if !path.is_file(){return Ok(None)}let bytes=std::fs::read(&path).map_err(|e|e.to_string())?;let expected=std::fs::read_to_string(dir.join(generation).join("overlay.sha256")).map_err(|e|e.to_string())?;if content_hash(&bytes)!=expected{return Err("overlay manifest checksum mismatch".into())}let m:Value=serde_json::from_slice(&bytes).map_err(|e|e.to_string())?;let base=m["base_generation"].as_str().ok_or("missing base generation")?;if !valid_generation(base){return Err("invalid base generation".into())}if !dir.join(base).is_dir(){let embedded=dir.join(generation);if !embedded.join("metadata.json").is_file()||!embedded.join("index.faiss").is_file(){return Err("base generation missing".into())}return Ok(Some(generation.to_owned()))}Ok(Some(base.to_owned()))}
pub fn search(model:&Encoder,dir:&Path,q:&str,filter:Option<&[&str]>,k:usize)->Result<Vec<Value>,String>{let vector:[f32;512]=model.encode(q,true)?.try_into().map_err(|_|"invalid dimensions")?;search_vector(model.identity(),dir,&vector,filter,k)}
/// Caller must keep workspace_lock while reading generation files.
pub fn search_vector(identity:&str,dir:&Path,vector:&[f32;512],filter:Option<&[&str]>,k:usize)->Result<Vec<Value>,String>{
 let generation=current(dir)?;
 if !dir.join(&generation).join("overlay.json").is_file(){let base=dir.join(generation);let data=read_json(&base.join("metadata.json"))?;if data["key"]!=identity{return Err("model key mismatch".into())}let records=records(&data)?;if data["index_sha256"]!=digest(&base.join("index.faiss"))?{return Err("index checksum mismatch".into())}let index=Index::load(&base.join("index.faiss")).map_err(str::to_string)?;if index.count()!=records.len() as i64{return Err("index and records count mismatch".into())}let ids=records.iter().enumerate().filter(|(_,x)|filter.is_none_or(|f|f.contains(&x["id"].as_str().unwrap_or("")))).map(|(i,_)|i as i64).collect::<Vec<_>>();return index.search(vector,&ids,k).map_err(str::to_string)?.into_iter().map(|(id,score)|{let mut row=records.get(id as usize).ok_or("index mismatch")?.clone();row["score"]=json!(score);Ok(row)}).collect()}
 let loaded=load(dir,identity)?;let base=group(records(&loaded.base_data)?)?;let delta=group(&loaded.delta_rows)?;let snapshot=loaded.snapshot.ok_or("missing delta")?;let changed:HashSet<String>=snapshot.changed_keys.iter().cloned().collect();let keys=records(&loaded.base_data)?.iter().map(|r|r["id"].as_str().unwrap_or("").to_owned()).collect();let overlay=FlatOverlay::from_snapshot(loaded.base_index,keys,snapshot)?;let filter=filter.map(|v|v.iter().map(|s|s.to_string()).collect::<Vec<_>>());overlay.search(vector,filter.as_deref(),k)?.into_iter().map(|(id,pos,score)|{let row=if changed.contains(&id){delta.get(&id)}else{base.get(&id)}.and_then(|v|v.get(pos)).ok_or("missing result metadata")?;let mut out=row.clone();out["score"]=json!(score);Ok(out)}).collect()
}

/// Stage a verified external index without publishing it as the local current index.
/// The normal source fingerprint and model checks still gate publication.
pub fn prepare_from_worker(model:&Encoder,docs:&[Source<'_>],images:impl Iterator<Item=Result<(String,String,Vec<u8>,String),String>>,trash:&[String],dir:&Path,worker:&Path,should_continue:impl Fn()->bool,progress:impl Fn(&str,usize,usize))->Result<Option<Prepared>,String>{
 use std::{io::Read,os::unix::fs::OpenOptionsExt};
 fn read(path:&Path)->Result<Vec<u8>,String>{let mut f=std::fs::OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(path).map_err(|e|e.to_string())?;if !f.metadata().map_err(|e|e.to_string())?.is_file(){return Err("invalid worker file".into())}let mut b=Vec::new();f.read_to_end(&mut b).map_err(|e|e.to_string())?;Ok(b)}
 fn sync_write(path:&Path,data:&[u8])->Result<(),String>{let mut f=std::fs::OpenOptions::new().write(true).create_new(true).open(path).map_err(|e|e.to_string())?;f.write_all(data).and_then(|_|f.sync_all()).map_err(|e|e.to_string())}
 fn sync_dir(path:&Path)->Result<(),String>{std::fs::File::open(path).and_then(|f|f.sync_all()).map_err(|e|e.to_string())}
 fn adjust(rows:&mut Value){if let Some(rows)=rows.as_array_mut(){for row in rows{if row["field"]=="image"{if let Some(k)=row["input_hash"].as_str(){if let Some((_,hash))=k.strip_prefix("image:").and_then(|x|x.split_once(':')){row["input_hash"]=json!(format!("image:{hash}"));}}}}}}
 if dir.join("current").exists()||!worker.join("current").exists(){return Ok(None)}
 let current=String::from_utf8(read(&worker.join("current"))?).map_err(|e|e.to_string())?;if !valid_generation(&current){return Err("invalid worker generation".into())}let active=worker.join(&current);if !std::fs::symlink_metadata(&active).map_err(|e|e.to_string())?.file_type().is_dir(){return Err("invalid worker generation".into())}
 let manifest=match read(&active.join("overlay.json")){Ok(bytes)=>{let checksum=String::from_utf8(read(&active.join("overlay.sha256"))?).map_err(|e|e.to_string())?;if checksum!=content_hash(&bytes){return Err("worker overlay checksum mismatch".into())}Some(serde_json::from_slice::<Value>(&bytes).map_err(|e|e.to_string())?)},Err(_) if !active.join("overlay.json").exists()=>None,Err(e)=>return Err(e)};
 let base_name=match &manifest{Some(m)=>m["base_generation"].as_str().ok_or("invalid worker base")?.to_owned(),None=>current.clone()};if !valid_generation(&base_name){return Err("invalid worker base".into())}let base=if worker.join(&base_name).is_dir(){worker.join(&base_name)}else{active.clone()};if !std::fs::symlink_metadata(&base).map_err(|e|e.to_string())?.file_type().is_dir(){return Err("invalid worker base".into())}
 let meta_bytes=read(&base.join("metadata.json"))?;let meta_sha=content_hash(&meta_bytes);let stored=String::from_utf8(read(&base.join("metadata.sha256"))?).map_err(|e|e.to_string())?;if stored!=meta_sha{return Err("worker metadata checksum mismatch".into())}let mut meta:Value=serde_json::from_slice(&meta_bytes).map_err(|e|e.to_string())?;if meta["model"].as_str()!=Some(model.identity()){return Ok(None)}
 let source_index=base.join("index.faiss");let index_meta=std::fs::symlink_metadata(&source_index).map_err(|e|e.to_string())?;if !index_meta.file_type().is_file(){return Err("invalid worker index".into())}let index_sha=digest(&source_index)?;if meta["index_sha256"].as_str()!=Some(&index_sha){return Err("worker index checksum mismatch".into())}if let Some(m)=&manifest{if m["key"].as_str()!=Some(model.identity())||m["base_metadata_sha256"].as_str()!=Some(&meta_sha)||m["base_index_sha256"].as_str()!=Some(&index_sha){return Err("worker overlay base mismatch".into())}}
 let delta=if let Some(m)=&manifest{let b=read(&active.join("delta.faiss"))?;if m["delta_sha256"].as_str()!=Some(&content_hash(&b)){return Err("worker delta checksum mismatch".into())}Some(b)}else{None};
 std::fs::create_dir_all(dir).map_err(|e|e.to_string())?;let serial=format!("{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos());let temp=dir.join(format!(".worker-import-{serial}"));std::fs::create_dir(&temp).map_err(|e|e.to_string())?;let mut moved=Vec::new();
 let result=(||->Result<Prepared,String>{let base_name=format!("gen-{serial}-base");let active_name=format!("gen-{serial}");let stage_base=temp.join(&base_name);std::fs::create_dir(&stage_base).map_err(|e|e.to_string())?;meta["key"]=json!(model.identity());meta.as_object_mut().ok_or("invalid metadata")?.remove("model");adjust(&mut meta["records"]);let metadata=serde_json::to_vec(&meta).map_err(|e|e.to_string())?;sync_write(&stage_base.join("metadata.json"),&metadata)?;let target_index=stage_base.join("index.faiss");if std::fs::hard_link(&source_index,&target_index).is_err(){let mut input=std::fs::OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC).open(&source_index).map_err(|e|e.to_string())?;let mut out=std::fs::OpenOptions::new().write(true).create_new(true).open(&target_index).map_err(|e|e.to_string())?;std::io::copy(&mut input,&mut out).map_err(|e|e.to_string())?;out.sync_all().map_err(|e|e.to_string())?;}if digest(&target_index)?!=index_sha{return Err("worker index copy checksum mismatch".into())}sync_dir(&stage_base)?;
 let seed=if let Some(mut m)=manifest{let stage=temp.join(&active_name);std::fs::create_dir(&stage).map_err(|e|e.to_string())?;embed_base(&stage_base,&stage)?;sync_write(&stage.join("delta.faiss"),delta.as_ref().ok_or("missing delta")?)?;m["base_generation"]=json!(base_name);m["base_metadata_sha256"]=json!(content_hash(&metadata));adjust(&mut m["delta_metadata"]);let bytes=serde_json::to_vec(&m).map_err(|e|e.to_string())?;sync_write(&stage.join("overlay.json"),&bytes)?;sync_write(&stage.join("overlay.sha256"),content_hash(&bytes).as_bytes())?;sync_dir(&stage)?;active_name}else{base_name};sync_write(&temp.join("current"),seed.as_bytes())?;sync_dir(&temp)?;
 let prepared=prepare_with_trash(model,docs,images,trash,&temp,&should_continue,progress)?;if !should_continue(){return Err("indexing cancelled".into())}let base=base_generation(&temp,&prepared.generation)?;let mut names=Vec::new();if let Some(base)=base {if base!=prepared.generation{names.push(base);}}names.push(prepared.generation.clone());for name in names{let target=dir.join(&name);std::fs::rename(temp.join(&name),&target).map_err(|e|e.to_string())?;moved.push(target);}sync_dir(dir)?;Ok(Prepared{generation:prepared.generation,owned:true})})();if result.is_err(){for path in moved {let _=std::fs::remove_dir_all(path);}}let _=std::fs::remove_dir_all(temp);result.map(Some)
}
